style.css:
@-moz-document domain("roblox.com") {
/* Fundo com GIF */
  body {
    background: url("https://media.giphy.com/media/xT9IgG50Fb7Mi0prBC/giphy.gif") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #333 !important; /* texto cinza escuro */
  }

  /* Seções principais transparentes com leve branco */
  .content, .container, .main-content, .game-page, .rbx-body {
    background: rgba(255, 255, 255, 0.8) !important;
    border-radius: 12px !important;
    box-shadow: 0 0 10px rgba(255, 192, 203, 0.3) !important;
  }

  /* Texto geral */
  * {
    color: #333 !important; /* texto escuro para contraste */
  }

  /* Barra superior (navbar) — rosa bebê */
  .navbar, .nav-container, .navigation-container {
    background-color: #ffd6e7 !important; /* rosa bem claro */
    border-bottom: 2px solid #ffb6d5 !important;
  }

  /* Ícones e texto do topo */
  .navbar a, .nav-item, .nav-text {
    color: #4a4a4a !important;
  }

  /* Barra lateral — rosa pastel com branco */
  .left-col, .menu, .side-menu {
    background-color: #ffeaf2 !important;
    color: #4a4a4a !important;
  }

  .menu a, .menu-item a {
    color: #4a4a4a !important;
    border-radius: 8px !important;
  }

  .menu a:hover, .menu-item:hover {
    background-color: #ffcfe1 !important; /* rosa bebê hover */
    color: #333 !important;
  }

  /* Botões */
  button, .btn, .rbx-btn-primary, .rbx-btn-secondary {
    background-color: #ffb6d5 !important; /* rosa bebê */
    color: #ffffff !important;
    border: none !important;
    border-radius: 10px !important;
    transition: all 0.3s ease !important;
  }

  /* Hover dos botões */
  button:hover, .btn:hover, .rbx-btn-primary:hover, .rbx-btn-secondary:hover {
    background-color: #ffcfe1 !important; /* rosa mais claro */
  }

  /* Caixa dos jogos */
  .game-card, .section, .container-section {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 12px !important;
  }

  /* Chat */
  .chat-container, .chat-window, .chat-message {
    background-color: rgba(255, 235, 245, 0.9) !important;
    color: #333 !important;
  }
}
